("SRC"."FILE_NAME" as STRING), '**NULL**') <> NVL( CAST("TGT"."FILE_NAME" as STRING), '**NULL**') OR NVL( CAST("SRC"."VENDOR_ID" as STRING), '**NULL**') <> NVL( CAST("TGT"."VENDOR_ID" as STRING), '**NULL**') OR NVL( CAST("SRC"."PAYMENT_TYPE_ID" as STRING), '**NULL**') <> NVL( CAST("TGT"."PAYMENT_TYPE_ID" as STRING), '**NULL**') OR NVL( CAST("SRC"."RATE_CODE_ID" as STRING), '**NULL**') <> NVL( CAST("TGT"."RATE_CODE_ID" as STRING), '**NULL**') OR NVL( CAST("SRC"."PICKUP_DATETIME" as STRING), '**NULL**') <> NVL( CAST("TGT"."PICKUP_DATETIME" as STRING), '**NULL**') OR NVL( CAST("SRC"."DROPOFF_DATETIME" as STRING), '**NULL**') <> NVL( CAST("TGT"."DROPOFF_DATETIME" as STRING), '**NULL**') OR NVL( CAST("SRC"."DO_LOCATION_ID" as STRING), '**NULL**') <> NVL( CAST("TGT"."DO_LOCATION_ID" as STRING), '**NULL**') OR NVL( CAST("SRC"."PU_LOCATION_ID" as STRING), '**NULL**') <> NVL( CAST("TGT"."PU_LOCATION_ID" as STRING), '**NULL**') OR NVL( CAST("SRC"."TRIP_DISTANCE" as STRING), '**NULL**') <> NVL( CAST("TGT"."TRIP_DISTANCE" as STRING), '**NULL**') OR NVL( CAST("SRC"."AIRPORT_FEE" as STRING), '**NULL**') <> NVL( CAST("TGT"."AIRPORT_FEE" as STRING), '**NULL**') OR NVL( CAST("SRC"."CBD_CONGESTION_FEE" as STRING), '**NULL**') <> NVL( CAST("TGT"."CBD_CONGESTION_FEE" as STRING), '**NULL**') OR NVL( CAST("SRC"."CONGESTION_SURCHARGE" as STRING), '**NULL**') <> NVL( CAST("TGT"."CONGESTION_SURCHARGE" as STRING), '**NULL**') OR NVL( CAST("SRC"."EXTRA" as STRING), '**NULL**') <> NVL( CAST("TGT"."EXTRA" as STRING), '**NULL**') OR NVL( CAST("SRC"."FARE_AMOUNT" as STRING), '**NULL**') <> NVL( CAST("TGT"."FARE_AMOUNT" as STRING), '**NULL**') OR NVL( CAST("SRC"."IMPROVEMENT_SURCHARGE" as STRING), '**NULL**') <> NVL( CAST("TGT"."IMPROVEMENT_SURCHARGE" as STRING), '**NULL**') OR NVL( CAST("SRC"."MTA_TAX" as STRING), '**NULL**') <> NVL( CAST("TGT"."MTA_TAX" as STRING), '**NULL**') OR NVL( CAST("SRC"."PASSENGER_COUNT" as STRING), '**NULL**') <> NVL( CAST("TGT"."PASSENGER_COUNT" as STRING), '**NULL**') OR NVL( CAST("SRC"."STORE_AND_FWD_FLAG" as STRING), '**NULL**') <> NVL( CAST("TGT"."STORE_AND_FWD_FLAG" as STRING), '**NULL**') OR NVL( CAST("SRC"."TIP_AMOUNT" as STRING), '**NULL**') <> NVL( CAST("TGT"."TIP_AMOUNT" as STRING), '**NULL**') OR NVL( CAST("SRC"."TOLLS_AMOUNT" as STRING), '**NULL**') <> NVL( CAST("TGT"."TOLLS_AMOUNT" as STRING), '**NULL**') OR NVL( CAST("SRC"."TOTAL_AMOUNT" as STRING), '**NULL**') <> NVL( CAST("TGT"."TOTAL_AMOUNT" as STRING), '**NULL**') OR NVL( CAST("SRC"."TPEP_PICKUP_DATETIME" as STRING), '**NULL**') <> NVL( CAST("TGT"."TPEP_PICKUP_DATETIME" as STRING), '**NULL**') OR NVL( CAST("SRC"."TPEP_DROPOFF_DATETIME" as STRING), '**NULL**') <> NVL( CAST("TGT"."TPEP_DROPOFF_DATETIME" as STRING), '**NULL**') ) THEN UPDATE SET "TGT"."FILE_NAME" = "SRC"."FILE_NAME" , "TGT"."VENDOR_ID" = "SRC"."VENDOR_ID" , "TGT"."PAYMENT_TYPE_ID" = "SRC"."PAYMENT_TYPE_ID" , "TGT"."RATE_CODE_ID" = "SRC"."RATE_CODE_ID" , "TGT"."PICKUP_DATETIME" = "SRC"."PICKUP_DATETIME" , "TGT"."DROPOFF_DATETIME" = "SRC"."DROPOFF_DATETIME" , "TGT"."DO_LOCATION_ID" = "SRC"."DO_LOCATION_ID" , "TGT"."PU_LOCATION_ID" = "SRC"."PU_LOCATION_ID" , "TGT"."TRIP_DISTANCE" = "SRC"."TRIP_DISTANCE" , "TGT"."AIRPORT_FEE" = "SRC"."AIRPORT_FEE" , "TGT"."CBD_CONGESTION_FEE" = "SRC"."CBD_CONGESTION_FEE" , "TGT"."CONGESTION_SURCHARGE" = "SRC"."CONGESTION_SURCHARGE" , "TGT"."EXTRA" = "SRC"."EXTRA" , "TGT"."FARE_AMOUNT" = "SRC"."FARE_AMOUNT" , "TGT"."IMPROVEMENT_SURCHARGE" = "SRC"."IMPROVEMENT_SURCHARGE" , "TGT"."MTA_TAX" = "SRC"."MTA_TAX" , "TGT"."PASSENGER_COUNT" = "SRC"."PASSENGER_COUNT" , "TGT"."STORE_AND_FWD_FLAG" = "SRC"."STORE_AND_FWD_FLAG" , "TGT"."TIP_AMOUNT" = "SRC"."TIP_AMOUNT" , "TGT"."TOLLS_AMOUNT" = "SRC"."TOLLS_AMOUNT" , "TGT"."TOTAL_AMOUNT" = "SRC"."TOTAL_AMOUNT" , "TGT"."TPEP_PICKUP_DATETIME" = "SRC"."TPEP_PICKUP_DATETIME" , "TGT"."TPEP_DROPOFF_DATETIME" = "SRC"."TPEP_DROPOFF_DATETIME" , "TGT"."SYSTEM_UPDATE_DATE" = "SRC"."SYSTEM_UPDATE_DATE" WHEN NOT MATCHED THEN INSERT ( "FILE_NAME" , "VENDOR_ID" , "PAYMENT_TYPE_ID" , "RATE_CODE_ID" , "PICKUP_DATETIME" , "DROPOFF_DATETIME" , "DO_LOCATION_ID" , "PU_LOCATION_ID" , "TRIP_DISTANCE" , "AIRPORT_FEE" , "CBD_CONGESTION_FEE" , "CONGESTION_SURCHARGE" , "EXTRA" , "FARE_AMOUNT" , "IMPROVEMENT_SURCHARGE" , "MTA_TAX" , "PASSENGER_COUNT" , "STORE_AND_FWD_FLAG" , "TIP_AMOUNT" , "TOLLS_AMOUNT" , "TOTAL_AMOUNT" , "TPEP_PICKUP_DATETIME" , "TPEP_DROPOFF_DATETIME" , "TRIP_ID" , "SYSTEM_VERSION" , "SYSTEM_CURRENT_FLAG" , "SYSTEM_START_DATE" , "SYSTEM_END_DATE" , "SYSTEM_CREATE_DATE" , "SYSTEM_UPDATE_DATE" ) VALUES ( "SRC"."FILE_NAME" , "SRC"."VENDOR_ID" , "SRC"."PAYMENT_TYPE_ID" , "SRC"."RATE_CODE_ID" , "SRC"."PICKUP_DATETIME" , "SRC"."DROPOFF_DATETIME" , "SRC"."DO_LOCATION_ID" , "SRC"."PU_LOCATION_ID" , "SRC"."TRIP_DISTANCE" , "SRC"."AIRPORT_FEE" , "SRC"."CBD_CONGESTION_FEE" , "SRC"."CONGESTION_SURCHARGE" , "SRC"."EXTRA" , "SRC"."FARE_AMOUNT" , "SRC"."IMPROVEMENT_SURCHARGE" , "SRC"."MTA_TAX" , "SRC"."PASSENGER_COUNT" , "SRC"."STORE_AND_FWD_FLAG" , "SRC"."TIP_AMOUNT" , "SRC"."TOLLS_AMOUNT" , "SRC"."TOTAL_AMOUNT" , "SRC"."TPEP_PICKUP_DATETIME" , "SRC"."TPEP_DROPOFF_DATETIME" , "SRC"."TRIP_ID" , "SRC"."SYSTEM_VERSION" , "SRC"."SYSTEM_CURRENT_FLAG" , "SRC"."SYSTEM_START_DATE" , "SRC"."SYSTEM_END_DATE" , "SRC"."SYSTEM_CREATE_DATE" , "SRC"."SYSTEM_UPDATE_DATE" ) ;\cell \row

