\cf0 INSERT INTO "NY_TAXI"."SILVER"."STG_YELLOW_CAB_TRIPS" ( "TRIP_ID", "VENDOR_ID", "PAYMENT_TYPE_ID", "RATE_CODE_ID", "PICKUP_DATETIME", "DROPOFF_DATETIME", "DO_LOCATION_ID", "PU_LOCATION_ID", "TRIP_DISTANCE", "TRIP_DURATION_MINUTES", "TRIP_AVG_SPEED", "PICKUP_TIME_OF_DAY", "AIRPORT_FEE", "CBD_CONGESTION_FEE", "CONGESTION_SURCHARGE", "EXTRA", "FARE_AMOUNT", "IMPROVEMENT_SURCHARGE", "MTA_TAX", "PASSENGER_COUNT", "STORE_AND_FWD_FLAG", "TIP_AMOUNT", "TOLLS_AMOUNT", "TOTAL_AMOUNT", "TPEP_PICKUP_DATETIME", "TPEP_DROPOFF_DATETIME", "COALESCE_RUN_ID" ) SELECT "YELLOW_CAB_TRIPS"."TRIP_ID" AS "TRIP_ID", "YELLOW_CAB_TRIPS"."VENDOR_ID" AS "VENDOR_ID", "YELLOW_CAB_TRIPS"."PAYMENT_TYPE_ID" AS "PAYMENT_TYPE_ID", "YELLOW_CAB_TRIPS"."RATE_CODE_ID" AS "RATE_CODE_ID", "YELLOW_CAB_TRIPS"."PICKUP_DATETIME" AS "PICKUP_DATETIME", "YELLOW_CAB_TRIPS"."DROPOFF_DATETIME" AS "DROPOFF_DATETIME", "YELLOW_CAB_TRIPS"."DO_LOCATION_ID" AS "DO_LOCATION_ID", "YELLOW_CAB_TRIPS"."PU_LOCATION_ID" AS "PU_LOCATION_ID", "YELLOW_CAB_TRIPS"."TRIP_DISTANCE" AS "TRIP_DISTANCE", DATEDIFF(MINUTE, PICKUP_DATETIME, DROPOFF_DATETIME) AS "TRIP_DURATION_MINUTES", DIV0(TRIP_DISTANCE, TRIP_DURATION_MINUTES) * 60 AS "TRIP_AVG_SPEED", CASE WHEN DATEDIFF(HOUR, TO_DATE(PICKUP_DATETIME), PICKUP_DATETIME) < 12 THEN 'MORNING' ELSE 'AFTERNOON' END AS "PICKUP_TIME_OF_DAY", "YELLOW_CAB_TRIPS"."AIRPORT_FEE" AS "AIRPORT_FEE", "YELLOW_CAB_TRIPS"."CBD_CONGESTION_FEE" AS "CBD_CONGESTION_FEE", "YELLOW_CAB_TRIPS"."CONGESTION_SURCHARGE" AS "CONGESTION_SURCHARGE", "YELLOW_CAB_TRIPS"."EXTRA" AS "EXTRA", "YELLOW_CAB_TRIPS"."FARE_AMOUNT" AS "FARE_AMOUNT", "YELLOW_CAB_TRIPS"."IMPROVEMENT_SURCHARGE" AS "IMPROVEMENT_SURCHARGE", "YELLOW_CAB_TRIPS"."MTA_TAX" AS "MTA_TAX", "YELLOW_CAB_TRIPS"."PASSENGER_COUNT" AS "PASSENGER_COUNT", "YELLOW_CAB_TRIPS"."STORE_AND_FWD_FLAG" AS "STORE_AND_FWD_FLAG", "YELLOW_CAB_TRIPS"."TIP_AMOUNT" AS "TIP_AMOUNT", "YELLOW_CAB_TRIPS"."TOLLS_AMOUNT" AS "TOLLS_AMOUNT", "YELLOW_CAB_TRIPS"."TOTAL_AMOUNT" AS "TOTAL_AMOUNT", "YELLOW_CAB_TRIPS"."TPEP_PICKUP_DATETIME" AS "TPEP_PICKUP_DATETIME", "YELLOW_CAB_TRIPS"."TPEP_DROPOFF_DATETIME" AS "TPEP_DROPOFF_DATETIME", PARSE_JSON(CURRENT_QUERY_TAG()):"coalesce"."runID"::NUMBER AS "COALESCE_RUN_ID" FROM "NY_TAXI"."BRONZE"."YELLOW_CAB_TRIPS" "YELLOW_CAB_TRIPS" WHERE TO_DATE("PICKUP_DATETIME") BETWEEN CURRENT_DATE - 10 AND CURRENT_DATE ;\cell \row

