\cf0 MERGE INTO "NY_TAXI"."GOLD"."DIM_RATE_CODE" "TGT" USING ( SELECT "STG_RATE_CODE"."RATE_CODE_ID" AS "RATE_CODE_ID", "STG_RATE_CODE"."RATE_CODE" AS "RATE_CODE", 1 AS "SYSTEM_VERSION", 'Y' AS "SYSTEM_CURRENT_FLAG", CAST(CURRENT_TIMESTAMP AS TIMESTAMP) AS "SYSTEM_START_DATE", CAST('2999-12-31 00:00:00' AS TIMESTAMP) AS "SYSTEM_END_DATE", CAST(CURRENT_TIMESTAMP AS TIMESTAMP) AS "SYSTEM_CREATE_DATE", CAST(CURRENT_TIMESTAMP AS TIMESTAMP) AS "SYSTEM_UPDATE_DATE" FROM "NY_TAXI"."SILVER"."STG_RATE_CODE" "STG_RATE_CODE") AS "SRC" ON "SRC"."RATE_CODE_ID" = "TGT"."RATE_CODE_ID" WHEN MATCHED AND ( NVL( CAST("SRC"."RATE_CODE" as STRING), '**NULL**') <> NVL( CAST("TGT"."RATE_CODE" as STRING), '**NULL**') ) THEN UPDATE SET "TGT"."RATE_CODE" = "SRC"."RATE_CODE" , "TGT"."SYSTEM_UPDATE_DATE" = "SRC"."SYSTEM_UPDATE_DATE" WHEN NOT MATCHED THEN INSERT ( "RATE_CODE_ID" , "RATE_CODE" , "SYSTEM_VERSION" , "SYSTEM_CURRENT_FLAG" , "SYSTEM_START_DATE" , "SYSTEM_END_DATE" , "SYSTEM_CREATE_DATE" , "SYSTEM_UPDATE_DATE" ) VALUES ( "SRC"."RATE_CODE_ID" , "SRC"."RATE_CODE" , "SRC"."SYSTEM_VERSION" , "SRC"."SYSTEM_CURRENT_FLAG" , "SRC"."SYSTEM_START_DATE" , "SRC"."SYSTEM_END_DATE" , "SRC"."SYSTEM_CREATE_DATE" , "SRC"."SYSTEM_UPDATE_DATE" ) ;\cell \row

