\cf0 MERGE INTO "NY_TAXI"."GOLD"."DIM_LOCATION" "TGT" USING ( SELECT "STG_LOCATION"."LOCATION_ID" AS "LOCATION_ID", "STG_LOCATION"."BOROUGH" AS "BOROUGH", "STG_LOCATION"."ZONE" AS "ZONE", "STG_LOCATION"."SERVICE_ZONE" AS "SERVICE_ZONE", "STG_LOCATION"."FILENAME" AS "FILENAME", 1 AS "SYSTEM_VERSION", 'Y' AS "SYSTEM_CURRENT_FLAG", CAST(CURRENT_TIMESTAMP AS TIMESTAMP) AS "SYSTEM_START_DATE", CAST('2999-12-31 00:00:00' AS TIMESTAMP) AS "SYSTEM_END_DATE", CAST(CURRENT_TIMESTAMP AS TIMESTAMP) AS "SYSTEM_CREATE_DATE", CAST(CURRENT_TIMESTAMP AS TIMESTAMP) AS "SYSTEM_UPDATE_DATE" FROM "NY_TAXI"."SILVER"."STG_LOCATION" "STG_LOCATION") AS "SRC" ON "SRC"."LOCATION_ID" = "TGT"."LOCATION_ID" WHEN MATCHED AND ( NVL( CAST("SRC"."BOROUGH" as STRING), '**NULL**') <> NVL( CAST("TGT"."BOROUGH" as STRING), '**NULL**') OR NVL( CAST("SRC"."ZONE" as STRING), '**NULL**') <> NVL( CAST("TGT"."ZONE" as STRING), '**NULL**') OR NVL( CAST("SRC"."SERVICE_ZONE" as STRING), '**NULL**') <> NVL( CAST("TGT"."SERVICE_ZONE" as STRING), '**NULL**') OR NVL( CAST("SRC"."FILENAME" as STRING), '**NULL**') <> NVL( CAST("TGT"."FILENAME" as STRING), '**NULL**') ) THEN UPDATE SET "TGT"."BOROUGH" = "SRC"."BOROUGH" , "TGT"."ZONE" = "SRC"."ZONE" , "TGT"."SERVICE_ZONE" = "SRC"."SERVICE_ZONE" , "TGT"."FILENAME" = "SRC"."FILENAME" , "TGT"."SYSTEM_UPDATE_DATE" = "SRC"."SYSTEM_UPDATE_DATE" WHEN NOT MATCHED THEN INSERT ( "LOCATION_ID" , "BOROUGH" , "ZONE" , "SERVICE_ZONE" , "FILENAME" , "SYSTEM_VERSION" , "SYSTEM_CURRENT_FLAG" , "SYSTEM_START_DATE" , "SYSTEM_END_DATE" , "SYSTEM_CREATE_DATE" , "SYSTEM_UPDATE_DATE" ) VALUES ( "SRC"."LOCATION_ID" , "SRC"."BOROUGH" , "SRC"."ZONE" , "SRC"."SERVICE_ZONE" , "SRC"."FILENAME" , "SRC"."SYSTEM_VERSION" , "SRC"."SYSTEM_CURRENT_FLAG" , "SRC"."SYSTEM_START_DATE" , "SRC"."SYSTEM_END_DATE" , "SRC"."SYSTEM_CREATE_DATE" , "SRC"."SYSTEM_UPDATE_DATE" ) ;\cell \row

