\pard\intbl\itap1\pardeftab720\partightenfactor0
\cf0 MERGE INTO "NY_TAXI"."GOLD"."DIM_VENDOR" "TGT" USING ( /* New Rows That Don't Exist */ SELECT "STG_VENDOR"."VENDOR_ID" AS "VENDOR_ID", "STG_VENDOR"."VENDOR_NAME" AS "VENDOR_NAME", "STG_VENDOR"."ADDRESS" AS "ADDRESS", "STG_VENDOR"."CITY" AS "CITY", "STG_VENDOR"."COUNTRY" AS "COUNTRY", "STG_VENDOR"."STATE" AS "STATE", "STG_VENDOR"."ZIP" AS "ZIP", "STG_VENDOR"."PHONE" AS "PHONE", "STG_VENDOR"."DRIVERS" AS "DRIVERS", 1 AS "SYSTEM_VERSION", 'Y' AS "SYSTEM_CURRENT_FLAG", CAST(CURRENT_TIMESTAMP AS TIMESTAMP) AS "SYSTEM_START_DATE", CAST('2999-12-31 00:00:00' AS TIMESTAMP) AS "SYSTEM_END_DATE", CAST(CURRENT_TIMESTAMP AS TIMESTAMP) AS "SYSTEM_CREATE_DATE", CAST(CURRENT_TIMESTAMP AS TIMESTAMP) AS "SYSTEM_UPDATE_DATE", 'INSERT_INITAL_VERSION_ROWS' AS "DML_OPERATION" FROM "NY_TAXI"."SILVER"."STG_VENDOR" "STG_VENDOR" LEFT JOIN "NY_TAXI"."GOLD"."DIM_VENDOR" "DIM" ON "STG_VENDOR"."VENDOR_ID" = "DIM"."VENDOR_ID" WHERE "DIM"."VENDOR_ID" IS NULL UNION ALL /* New Row Needing To Be Inserted Due To Type-2 Column Changes */ SELECT "STG_VENDOR"."VENDOR_ID" AS "VENDOR_ID", "STG_VENDOR"."VENDOR_NAME" AS "VENDOR_NAME", "STG_VENDOR"."ADDRESS" AS "ADDRESS", "STG_VENDOR"."CITY" AS "CITY", "STG_VENDOR"."COUNTRY" AS "COUNTRY", "STG_VENDOR"."STATE" AS "STATE", "STG_VENDOR"."ZIP" AS "ZIP", "STG_VENDOR"."PHONE" AS "PHONE", "STG_VENDOR"."DRIVERS" AS "DRIVERS", "DIM"."SYSTEM_VERSION" + 1 AS "SYSTEM_VERSION", 'Y' AS "SYSTEM_CURRENT_FLAG", CAST(CURRENT_TIMESTAMP AS TIMESTAMP) AS "SYSTEM_START_DATE", CAST('2999-12-31 00:00:00' AS TIMESTAMP) AS "SYSTEM_END_DATE", CAST(CURRENT_TIMESTAMP AS TIMESTAMP) AS "SYSTEM_CREATE_DATE", CAST(CURRENT_TIMESTAMP AS TIMESTAMP) AS "SYSTEM_UPDATE_DATE", 'INSERT_NEW_VERSION_ROWS' AS "DML_OPERATION" FROM "NY_TAXI"."SILVER"."STG_VENDOR" "STG_VENDOR" INNER JOIN "NY_TAXI"."GOLD"."DIM_VENDOR" "DIM" ON "STG_VENDOR"."VENDOR_ID" = "DIM"."VENDOR_ID" WHERE "DIM"."SYSTEM_CURRENT_FLAG" = 'Y' AND ( ( NVL( CAST("STG_VENDOR"."COUNTRY" as STRING), '**NULL**') <> NVL( CAST("DIM"."COUNTRY" as STRING), '**NULL**') ) OR ( NVL( CAST("STG_VENDOR"."STATE" as STRING), '**NULL**') <> NVL( CAST("DIM"."STATE" as STRING), '**NULL**') ) ) UNION ALL /* Rows Needing To Be Expired Due To Type-2 Column Changes In this case, only two columns are merged (version and end date) */ SELECT "DIM"."VENDOR_ID" AS "VENDOR_ID", "DIM"."VENDOR_NAME" AS "VENDOR_NAME", "DIM"."ADDRESS" AS "ADDRESS", "DIM"."CITY" AS "CITY", "DIM"."COUNTRY" AS "COUNTRY", "DIM"."STATE" AS "STATE", "DIM"."ZIP" AS "ZIP", "DIM"."PHONE" AS "PHONE", "DIM"."DRIVERS" AS "DRIVERS", "DIM"."SYSTEM_VERSION" AS "SYSTEM_VERSION", 'N' AS "SYSTEM_CURRENT_FLAG", "DIM"."SYSTEM_START_DATE" AS "SYSTEM_START_DATE", DATEADD(MILLISECONDS, -1, CAST(CURRENT_TIMESTAMP AS TIMESTAMP)) AS "SYSTEM_END_DATE", "DIM"."SYSTEM_CREATE_DATE" AS "SYSTEM_CREATE_DATE", "DIM"."SYSTEM_UPDATE_DATE" AS "SYSTEM_UPDATE_DATE", 'update_expired_version_rows' AS "DML_OPERATION" FROM "NY_TAXI"."SILVER"."STG_VENDOR" "STG_VENDOR" INNER JOIN "NY_TAXI"."GOLD"."DIM_VENDOR" "DIM" ON "STG_VENDOR"."VENDOR_ID" = "DIM"."VENDOR_ID" WHERE "DIM"."SYSTEM_CURRENT_FLAG" = 'Y' AND ( ( NVL( CAST("STG_VENDOR"."COUNTRY" as STRING), '**NULL**') <> NVL( CAST("DIM"."COUNTRY" as STRING), '**NULL**') ) OR ( NVL( CAST("STG_VENDOR"."STATE" as STRING), '**NULL**') <> NVL( CAST("DIM"."STATE" as STRING), '**NULL**') ) ) UNION ALL /* Rows Needing To Be Updated Due To Changes To Non-Type-2 columns This case merges only when there are changes in non-type-2 column updates, but no changes in type-2 columns*/ SELECT "STG_VENDOR"."VENDOR_ID" AS "VENDOR_ID", "STG_VENDOR"."VENDOR_NAME" AS "VENDOR_NAME", "STG_VENDOR"."ADDRESS" AS "ADDRESS", "STG_VENDOR"."CITY" AS "CITY", "STG_VENDOR"."COUNTRY" AS "COUNTRY", "STG_VENDOR"."STATE" AS "STATE", "STG_VENDOR"."ZIP" AS "ZIP", "STG_VENDOR"."PHONE" AS "PHONE", "STG_VENDOR"."DRIVERS" AS "DRIVERS", "DIM"."SYSTEM_VERSION" AS "SYSTEM_VERSION", 'Y' AS "SYSTEM_CURRENT_FLAG", "DIM"."SYSTEM_START_DATE" AS "SYSTEM_START_DATE", "DIM"."SYSTEM_END_DATE" AS "SYSTEM_END_DATE", "DIM"."SYSTEM_CREATE_DATE" AS "SYSTEM_CREATE_DATE", CAST(CURRENT_TIMESTAMP AS TIMESTAMP) AS "SYSTEM_UPDATE_DATE", 'UPDATE_NON_TYPE2_ROWS' AS "DML_OPERATION" FROM "NY_TAXI"."SILVER"."STG_VENDOR" "STG_VENDOR" INNER JOIN "NY_TAXI"."GOLD"."DIM_VENDOR" "DIM" ON "STG_VENDOR"."VENDOR_ID" = "DIM"."VENDOR_ID" WHERE "DIM"."SYSTEM_CURRENT_FLAG" = 'Y' AND ( "STG_VENDOR"."COUNTRY" = "DIM"."COUNTRY" AND "STG_VENDOR"."STATE" = "DIM"."STATE" ) AND ( NVL( CAST("STG_VENDOR"."VENDOR_NAME" as STRING), '**NULL**') <> NVL( CAST("DIM"."VENDOR_NAME" as STRING), '**NULL**') OR NVL( CAST("STG_VENDOR"."ADDRESS" as STRING), '**NULL**') <> NVL( CAST("DIM"."ADDRESS" as STRING), '**NULL**') OR NVL( CAST("STG_VENDOR"."CITY" as STRING), '**NULL**') <> NVL( CAST("DIM"."CITY" as STRING), '**NULL**') OR NVL( CAST("STG_VENDOR"."ZIP" as STRING), '**NULL**') <> NVL( CAST("DIM"."ZIP" as STRING), '**NULL**') OR NVL( CAST("STG_VENDOR"."PHONE" as STRING), '**NULL**') <> NVL( CAST("DIM"."PHONE" as STRING), '**NULL**') OR NVL( CAST("STG_VENDOR"."DRIVERS" as STRING), '**NULL**') <> NVL( CAST("DIM"."DRIVERS" as STRING), '**NULL**') ) ) AS "SRC" ON "TGT"."VENDOR_ID" = "SRC"."VENDOR_ID" AND "TGT"."SYSTEM_VERSION" = "SRC"."SYSTEM_VERSION" WHEN MATCHED THEN UPDATE SET "TGT"."VENDOR_NAME" = "SRC"."VENDOR_NAME" , "TGT"."ADDRESS" = "SRC"."ADDRESS" , "TGT"."CITY" = "SRC"."CITY" , "TGT"."COUNTRY" = "SRC"."COUNTRY" , "TGT"."STATE" = "SRC"."STATE" , "TGT"."ZIP" = "SRC"."ZIP" , "TGT"."PHONE" = "SRC"."PHONE" , "TGT"."DRIVERS" = "SRC"."DRIVERS" , "TGT"."SYSTEM_VERSION" = "SRC"."SYSTEM_VERSION" , "TGT"."SYSTEM_CURRENT_FLAG" = "SRC"."SYSTEM_CURRENT_FLAG" , "TGT"."SYSTEM_START_DATE" = "SRC"."SYSTEM_START_DATE" , "TGT"."SYSTEM_END_DATE" = "SRC"."SYSTEM_END_DATE" , "TGT"."SYSTEM_UPDATE_DATE" = "SRC"."SYSTEM_UPDATE_DATE" WHEN NOT MATCHED THEN INSERT ( "VENDOR_ID" , "VENDOR_NAME" , "ADDRESS" , "CITY" , "COUNTRY" , "STATE" , "ZIP" , "PHONE" , "DRIVERS" , "SYSTEM_VERSION" , "SYSTEM_CURRENT_FLAG" , "SYSTEM_START_DATE" , "SYSTEM_END_DATE" , "SYSTEM_CREATE_DATE" , "SYSTEM_UPDATE_DATE" ) VALUES ( "SRC"."VENDOR_ID" , "SRC"."VENDOR_NAME" , "SRC"."ADDRESS" , "SRC"."CITY" , "SRC"."COUNTRY" , "SRC"."STATE" , "SRC"."ZIP" , "SRC"."PHONE" , "SRC"."DRIVERS" , "SRC"."SYSTEM_VERSION" , "SRC"."SYSTEM_CURRENT_FLAG" , "SRC"."SYSTEM_START_DATE" , "SRC"."SYSTEM_END_DATE" , "SRC"."SYSTEM_CREATE_DATE" , "SRC"."SYSTEM_UPDATE_DATE" ) ;\cell \row

