STG_YELLOW_CAB_TRIPS"."AIRPORT_FEE" AS "AIRPORT_FEE", "STG_YELLOW_CAB_TRIPS"."CBD_CONGESTION_FEE" AS "CBD_CONGESTION_FEE", "STG_YELLOW_CAB_TRIPS"."CONGESTION_SURCHARGE" AS "CONGESTION_SURCHARGE", "STG_YELLOW_CAB_TRIPS"."EXTRA" AS "EXTRA", "STG_YELLOW_CAB_TRIPS"."FARE_AMOUNT" AS "FARE_AMOUNT", "STG_YELLOW_CAB_TRIPS"."IMPROVEMENT_SURCHARGE" AS "IMPROVEMENT_SURCHARGE", "STG_YELLOW_CAB_TRIPS"."MTA_TAX" AS "MTA_TAX", "STG_YELLOW_CAB_TRIPS"."PASSENGER_COUNT" AS "PASSENGER_COUNT", "STG_YELLOW_CAB_TRIPS"."STORE_AND_FWD_FLAG" AS "STORE_AND_FWD_FLAG", "STG_YELLOW_CAB_TRIPS"."TIP_AMOUNT" AS "TIP_AMOUNT", "STG_YELLOW_CAB_TRIPS"."TOLLS_AMOUNT" AS "TOLLS_AMOUNT", "STG_YELLOW_CAB_TRIPS"."TOTAL_AMOUNT" AS "TOTAL_AMOUNT", "STG_YELLOW_CAB_TRIPS"."COALESCE_RUN_ID" AS "COALESCE_RUN_ID" FROM "NY_TAXI"."SILVER"."STG_YELLOW_CAB_TRIPS" "STG_YELLOW_CAB_TRIPS" LEFT JOIN "NY_TAXI"."GOLD"."DIM_VENDOR" "DIM_VENDOR" ON "STG_YELLOW_CAB_TRIPS"."VENDOR_ID"= "DIM_VENDOR"."VENDOR_ID" AND "STG_YELLOW_CAB_TRIPS"."PICKUP_DATETIME" BETWEEN "DIM_VENDOR"."SYSTEM_START_DATE" AND "DIM_VENDOR"."SYSTEM_END_DATE" LEFT JOIN "NY_TAXI"."GOLD"."DIM_PAYMENT_TYPE" "DIM_PAYMENT_TYPE" ON "STG_YELLOW_CAB_TRIPS"."PAYMENT_TYPE_ID" = "DIM_PAYMENT_TYPE"."PAYMENT_TYPE_ID" LEFT JOIN "NY_TAXI"."GOLD"."DIM_RATE_CODE" "DIM_RATE_CODE" ON "STG_YELLOW_CAB_TRIPS"."RATE_CODE_ID" = "DIM_RATE_CODE"."RATE_CODE_ID" INNER JOIN "NY_TAXI"."SILVER"."PICKUP_LOCATION" "PICKUP_LOCATION" ON "STG_YELLOW_CAB_TRIPS"."PU_LOCATION_ID" = "PICKUP_LOCATION"."LOCATION_ID" INNER JOIN "NY_TAXI"."SILVER"."DROPOFF_LOCATION" "DROPOFF_LOCATION" ON "STG_YELLOW_CAB_TRIPS"."DO_LOCATION_ID" = "DROPOFF_LOCATION"."LOCATION_ID" ;\cell \row

